const uris = new Map<string, string>();

/** The blurred placeholder as a CSS url(): the tiny WebP inside an SVG with a Gaussian blur, so it scales up smoothly. */
export function lqipUrl(key: string): string | undefined {
  const d = DATA[key];
  if (!d) return undefined;
  let u = uris.get(key);
  if (!u) {
    const [w, h, b64] = d;
    const svg =
      `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 ${w} ${h}' preserveAspectRatio='none'>` +
      `<filter id='b' x='0' y='0' width='1' height='1' color-interpolation-filters='sRGB'><feGaussianBlur stdDeviation='.8' edgeMode='duplicate'/></filter>` +
      `<image width='${w}' height='${h}' preserveAspectRatio='none' filter='url(#b)' href='data:image/webp;base64,${b64}'/></svg>`;
    u = `url("data:image/svg+xml,${svg.replace(/#/g, "%23").replace(/</g, "%3C").replace(/>/g, "%3E")}")`;
    uris.set(key, u);
  }
  return u;
}

/** Inline style that paints the placeholder behind an <img>/<video> (which covers it once loaded). */
export function lqipBg(key: string, position = "50% 50%"): CSSProperties {
  const url = lqipUrl(key);
  return url ? { backgroundImage: url, backgroundSize: "cover", backgroundPosition: position, backgroundRepeat: "no-repeat" } : {};
}

/** Placeholder key for a project's cover: the poster for films, the first still otherwise. */
export const coverKey = (slug: string, type: "film" | "stills") => (type === "film" ? `${slug}/poster` : `${slug}/01`);
